fn test_parse_const_with_scope_public() {
	// example: `[?const scope=public PUBLIC-VERSION "1.0"]`.
	n := cx.parse_const('[?const scope=public PUBLIC-VERSION "1.0"]') or {
		assert false, 'parse failed: ${err}'
		return
